import { BrowserRouter as Router, Route, Switch, useLocation } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { message, Modal } from 'antd'; // Assuming you're using Ant Design for Modal and message components
import Offline from './Offline'; // Assuming you have this component for offline detection
import Navbar from './Navbar'; // Import Navbar
import Hero from './Hero'; // Import Hero
import Signup from './Signup'; // Import Signup
import Login from './Login'; // Import Login
import ProtectedRoute from './ProtectedRoute'; // Assuming you have a custom ProtectedRoute component
import {
  TeacherDashboard,
  StudentDashboard,
  CreateTest,
  AttemptTest,
  Result,
  IndividualResult,
  TestInstruction,
  TestPreviewWrapper,
  Profile,
  AssignedTestsWrapper,
  TestStatus,
} from './components'; // Import the necessary components

function AppContent({ userInfo, selectedTestName, selectedAssignedTestName }) {
  const currentLocation = useLocation(); // Renamed 'location' to 'currentLocation'
  const [count, setCount] = useState(1);
  const role = userInfo.role;

  const handleOffline = () => {
    setCount((prevCount) => prevCount + 1);
    if (count % 2 === 0) {
      message.success("Connected to internet");
    } else {
      message.error("Please connect to internet");
    }
  };

  useEffect(() => {
    // Disable right-click context menu
    const preventContextMenu = (e) => e.preventDefault();
    window.addEventListener("contextmenu", preventContextMenu);

    // Disable F12 key
    const preventF12 = (e) => {
      if (e.key === "F12") {
        e.preventDefault();
      }
    };
    window.addEventListener("keydown", preventF12);

    return () => {
      window.removeEventListener("contextmenu", preventContextMenu);
      window.removeEventListener("keydown", preventF12);
    };
  }, []);

  return (
    <div className={count % 2 ? "" : " pointer__select__none"}>
      <Offline onChange={handleOffline} />

      {/* Conditionally render the Navbar, only if not on the "/" route */}
      {currentLocation.pathname !== "/" && <Navbar />}

      <Switch>
        <Route exact path="/" render={() => <Hero id="Front" />} />
        <Route exact path="/signup" component={Signup} />
        <Route exact path="/signin" component={Login} />
        <ProtectedRoute
          exact
          path="/dash"
          component={role === "teacher" ? TeacherDashboard : StudentDashboard}
        />
        <ProtectedRoute exact path="/attempt-test" component={AttemptTest} />
        <ProtectedRoute
          exact
          path="/create-test"
          component={role === "teacher" ? CreateTest : AttemptTest}
        />
        <ProtectedRoute exact path="/result" component={Result} />
        <ProtectedRoute
          exact
          path={`/result/${selectedTestName}`}
          component={IndividualResult}
        />
        <ProtectedRoute
          exact
          path="/test-instructions"
          component={TestInstruction}
        />
        <ProtectedRoute exact path="/start-test" component={TestPreviewWrapper} />
        <ProtectedRoute exact path="/profile" component={Profile} />
        <ProtectedRoute
          exact
          path="/assigned-test"
          component={role === "teacher" ? AssignedTestsWrapper : StudentDashboard}
        />
        <ProtectedRoute
          exact
          path={`/test-status/${selectedAssignedTestName}`}
          component={TestStatus}
        />
        <ProtectedRoute component={Login} />
      </Switch>
    </div>
  );
}

const mapStateToProps = (state) => {
  return {
    selectedTestName: state.selectedTest.selectedTestResultData.testName
      ?.replace(/\s+/g, "-")
      .toLowerCase(),
    userInfo: state.auth.user,
    selectedAssignedTestName: state.selectedTest.selectedAssignedTestData.testName
      ?.replace(/\s+/g, "-")
      .toLowerCase(),
  };
};

export default connect(mapStateToProps, null)(App);
